  1→/**
  2→ * USDExporter.js
  3→ *
  4→ * Export cognitive profiles as Universal Scene Description (USDA) format.
  5→ *
  6→ * THESIS: USD composition semantics (LIVRPS) map to cognitive priority.
  7→ * This is not scene description — it's AGENT STATE DESCRIPTION.
  8→ *
  9→ * The exported profile is designed to:
 10→ * 1. Reference the base CognitiveSubstrate in CLAUDE.md
 11→ * 2. Override default values via USD composition
 12→ * 3. Be verifiable via checksum
 13→ * 4. Be human-readable AND machine-parseable
 14→ *
 15→ * LIVRPS Priority (how USD merges opinions):
 16→ * - Local opinions (conversation context) — highest
 17→ * - Inherit from parent prims
 18→ * - Variants for mode switching
 19→ * - References to external assets ← TranslatorsProfile uses this
 20→ * - Payloads for deferred loading
 21→ * - Specialize for inheritance
 22→ */
 23→
 24→import { DIMENSION_CONFIG, DeterministicProfileEngine } from './DeterministicProfileEngine.js';
 25→import { VERSION } from '../config/version.js';
 26→import { renderProfileAsText, COGNITIVE_DOMAINS } from '../calibration/index.js';
 27→
 28→export class USDExporter {
 29→  /**
 30→   * Export profile as USDA (ASCII USD format)
 31→   *
 32→   * @param {Object} profile - Complete profile from DeterministicProfileEngine
 33→   * @param {Object} options - Export options
 34→   * @returns {string} Valid USDA content
 35→   */
 36→  static toUSDA(profile, options = {}) {
 37→    // Validate profile before export
 38→    const validation = DeterministicProfileEngine.validateProfile(profile);
 39→    if (!validation.valid) {
 40→      throw new Error(`Invalid profile: ${validation.errors.join(', ')}`);
 41→    }
 42→
 43→    const {
 44→      includeRaw = false,
 45→      referencePath = '/CognitiveSubstrate/Profile',
 46→      indent = '  '
 47→    } = options;
 48→
 49→    const timestamp = new Date().toISOString();
 50→
 51→    let usda = `#usda 1.0
 52→(
 53→    defaultPrim = "TranslatorsProfile"
 54→    doc = "Cognitive profile generated by The Translators interview game"
 55→    customLayerData = {
 56→        string generator = "The Translators v${profile.version || VERSION.profile}"
 57→        string checksum = "${profile.checksum}"
 58→        string anchor = "${profile.anchor}"
 59→        string generated = "${timestamp}"
 60→        string thesis = "USD as Universal State Description"
 61→    }
 62→)
 63→
 64→def "TranslatorsProfile" (
 65→    references = @${referencePath}@
 66→    doc = "Behavioral preferences derived from cognitive interview — overrides base profile"
 67→    kind = "component"
 68→)
 69→{
 70→${this.formatTraits(profile.traits, indent)}
 71→
 72→${this.formatInsights(profile.insights, indent)}
 73→
 74→${this.formatSignalPriority(profile.traits, indent)}
 75→}
 76→`;
 77→
 78→    if (includeRaw) {
 79→      usda += this.formatRawAnswers(profile.raw, indent);
 80→    }
 81→
 82→    return usda;
 83→  }
 84→
 85→  /**
 86→   * Format traits as USD custom attributes
 87→   */
 88→  static formatTraits(traits, indent = '  ') {
 89→    const sortedDims = Object.keys(traits).sort();
 90→    const lines = [`${indent}# === COGNITIVE TRAITS ===`];
 91→
 92→    sortedDims.forEach(dim => {
 93→      const trait = traits[dim];
 94→      lines.push(`${indent}# ${dim.charAt(0).toUpperCase() + dim.slice(1)}`);
 95→      lines.push(`${indent}custom string ${dim} = "${trait.label}"`);
 96→      lines.push(`${indent}custom float ${dim}:score = ${trait.value.toFixed(2)}`);
 97→      lines.push(`${indent}custom string ${dim}:behavior = "${this.escapeString(trait.behavior)}"`);
 98→      lines.push('');
 99→    });
100→
101→    return lines.join('\n');
102→  }
103→
104→  /**
105→   * Format insights as USD custom attributes
106→   */
107→  static formatInsights(insights, indent = '  ') {
108→    const lines = [`${indent}# === COMMUNICATION INSIGHTS ===`];
109→    lines.push(`${indent}custom string[] insights = [`);
110→
111→    insights.forEach((insight, i) => {
112→      const comma = i < insights.length - 1 ? ',' : '';
113→      lines.push(`${indent}${indent}"${this.escapeString(insight)}"${comma}`);
114→    });
115→
116→    lines.push(`${indent}]`);
117→    return lines.join('\n');
118→  }
119→
120→  /**
121→   * Format signal priority rules for AI consumption
122→   * These map traits to behavioral adjustments
123→   */
124→  static formatSignalPriority(traits, indent = '  ') {
125→    const lines = [`${indent}# === SIGNAL PRIORITY ===`];
126→    lines.push(`${indent}# Apply in order: emotional_state > mode_switch > domain > task_type`);
127→    lines.push(`${indent}custom string[] signal_overrides = [`);
128→
129→    const sortedDims = Object.keys(traits).sort();
130→    sortedDims.forEach((dim, i) => {
131→      const trait = traits[dim];
132→      const signal = this.traitToSignal(dim, trait);
133→      const comma = i < sortedDims.length - 1 ? ',' : '';
134→      lines.push(`${indent}${indent}"${signal}"${comma}`);
135→    });
136→
137→    lines.push(`${indent}]`);
138→    return lines.join('\n');
139→  }
140→
141→  /**
142→   * Convert trait to signal instruction
143→   */
144→  static traitToSignal(dimension, trait) {
145→    const signals = {
146→      pace: trait.value > 0.6 ? 'pace:deliberate → provide context before conclusions'
147→        : trait.value < 0.4 ? 'pace:quick → lead with the answer'
148→          : 'pace:adaptive → match user energy',
149→
150→      thoroughness: trait.value > 0.6 ? 'detail:high → include comprehensive information'
151→        : trait.value < 0.4 ? 'detail:minimal → start sparse, expand on request'
152→          : 'detail:balanced → appropriate depth for context',
153→
154→      organization: trait.value > 0.6 ? 'structure:ordered → use lists, steps, hierarchy'
155→        : trait.value < 0.4 ? 'structure:narrative → use stories and examples'
156→          : 'structure:mixed → blend as appropriate',
157→
158→      exploration: trait.value > 0.6 ? 'tangents:embrace → follow interesting threads'
159→        : trait.value < 0.4 ? 'tangents:redirect → stay on topic'
160→          : 'tangents:selective → follow good ones',
161→
162→      communication: trait.value > 0.6 ? 'feedback:gentle → encourage while correcting'
163→        : trait.value < 0.4 ? 'feedback:direct → tell it straight'
164→          : 'feedback:contextual → match situation',
165→
166→      ambiguity: trait.value > 0.6 ? 'uncertainty:explore → present possibilities'
167→        : trait.value < 0.4 ? 'uncertainty:clarify → be direct about unknowns'
168→          : 'uncertainty:balanced → honest assessment',
169→
170→      rhythm: trait.value > 0.6 ? 'pauses:embrace → silence is productive'
171→        : trait.value < 0.4 ? 'pauses:minimize → keep momentum'
172→          : 'pauses:natural → comfortable flow',
173→
174→      tangents: trait.value > 0.6 ? 'divergence:welcome → insights live in tangents'
175→        : trait.value < 0.4 ? 'divergence:limit → bring back on track'
176→          : 'divergence:curated → follow interesting ones'
177→    };
178→
179→    return signals[dimension] || `${dimension}:${trait.label.toLowerCase()}`;
180→  }
181→
182→  /**
183→   * Format raw answers for debugging/transparency
184→   */
185→  static formatRawAnswers(raw, indent = '  ') {
186→    if (!raw || Object.keys(raw).length === 0) return '';
187→
188→    const lines = ['\ndef "RawAnswers" ('];
189→    lines.push(`${indent}doc = "Original interview responses for transparency"`);
190→    lines.push(')');
191→    lines.push('{');
192→
193→    Object.entries(raw).forEach(([questionId, answer]) => {
194→      lines.push(`${indent}custom string ${questionId} = "${answer.value}"`);
195→      lines.push(`${indent}custom float ${questionId}:trait = ${answer.trait}`);
196→      lines.push(`${indent}custom int ${questionId}:depth = ${answer.depth}`);
197→    });
198→
199→    lines.push('}');
200→    return lines.join('\n');
201→  }
202→
203→  /**
204→   * Escape string for USD (handle quotes, newlines)
205→   */
206→  static escapeString(str) {
207→    return str
208→      .replace(/\\/g, '\\\\')
209→      .replace(/"/g, '\\"')
210→      .replace(/\n/g, '\\n')
211→      .replace(/'/g, "\\'");
212→  }
213→
214→  /**
215→   * Export as compact JSON-LD with USD context
216→   * Alternative format for web consumption
217→   */
218→  static toJSONLD(profile) {
219→    // Validate profile before export
220→    const validation = DeterministicProfileEngine.validateProfile(profile);
221→    if (!validation.valid) {
222→      throw new Error(`Invalid profile: ${validation.errors.join(', ')}`);
223→    }
224→
225→    return {
226→      '@context': {
227→        '@vocab': 'https://josephibrahim.com/translators/v1/',
228→        'usd': 'https://openusd.org/ns/',
229→        'traits': '@nest',
230→        'insights': '@list'
231→      },
232→      '@type': 'CognitiveProfile',
233→      '@id': `translators:profile:${profile.checksum}`,
234→      'usd:defaultPrim': 'TranslatorsProfile',
235→      'generator': VERSION.generator,
236→      'version': profile.version || VERSION.profile,
237→      'checksum': profile.checksum,
238→      'anchor': profile.anchor,
239→      'traits': Object.entries(profile.traits).reduce((acc, [dim, trait]) => {
240→        acc[dim] = {
241→          '@type': 'CognitiveTrait',
242→          'label': trait.label,
243→          'score': trait.value,
244→          'behavior': trait.behavior
245→        };
246→        return acc;
247→      }, {}),
248→      'insights': profile.insights
249→    };
250→  }
251→
252→  /**
253→   * Export as Markdown with embedded USD
254→   * Best format for CLAUDE.md integration
255→   */
256→  static toMarkdown(profile, options = {}) {
257→    // Validate profile before export
258→    const validation = DeterministicProfileEngine.validateProfile(profile);
259→    if (!validation.valid) {
260→      throw new Error(`Invalid profile: ${validation.errors.join(', ')}`);
261→    }
262→
263→    const {
264→      includeUSDA = true,
265→      title = 'Cognitive Profile'
