415→  static formatCognitiveDomains(profile, indent = '  ') {
416→    const domains = ['attention', 'workingMemory', 'timePerception', 'energy',
417→                     'motivation', 'processing', 'emotional', 'social'];
418→    const lines = [`${indent}# === COGNITIVE DOMAINS ===\n`];
419→
420→    for (const domain of domains) {
421→      const data = profile[domain];
422→      if (!data || Object.keys(data).length === 0) continue;
423→
424→      lines.push(`${indent}# ${domain.charAt(0).toUpperCase() + domain.slice(1)}`);
425→      lines.push(`${indent}def "${domain}" (`);
426→      lines.push(`${indent}${indent}doc = "Cognitive domain: ${domain}"`);
427→      lines.push(`${indent})`);
428→      lines.push(`${indent}{`);
429→
430→      // Format each attribute in the domain
431→      for (const [key, value] of Object.entries(data)) {
432→        if (value === null || value === undefined) continue;
433→
434→        const attrName = key.replace(/([A-Z])/g, '_$1').toLowerCase();
435→
436→        if (typeof value === 'number') {
437→          lines.push(`${indent}${indent}custom float ${attrName} = ${value.toFixed(3)}`);
438→        } else if (typeof value === 'boolean') {
439→          lines.push(`${indent}${indent}custom bool ${attrName} = ${value}`);
440→        } else if (Array.isArray(value)) {
441→          const arrayStr = value.map(v => `"${this.escapeString(String(v))}"`).join(', ');
442→          lines.push(`${indent}${indent}custom string[] ${attrName} = [${arrayStr}]`);
443→        } else {
444→          lines.push(`${indent}${indent}custom string ${attrName} = "${this.escapeString(String(value))}"`);
445→        }
446→      }
447→
448→      lines.push(`${indent}}`);
449→      lines.push('');
450→    }
451→
452→    return lines.join('\n');
453→  }
