 354→  selectAnswer(game, question, data) {
 355→    const answer = {
 356→      value: data.value,
 357→      trait: parseFloat(data.trait),
 358→      dimension: question.dimension,
 359→      depth: question.depth
 360→    };
 361→    this.answers[question.id] = answer;
 362→
 363→    // Track answer in cognitive manager for profile building
 364→    if (this.cognitiveManager) {
 365→      this.cognitiveManager.onLegacyQuestionAnswered(question.id, answer);
 366→    }
 367→
 368→    // EVOLVE the graphics — pass question.id for plant type selection
 369→    this.evolve(game, question.depth, parseFloat(data.trait), question.id);
 370→
 371→    this.currentQuestionIndex++;
 372→
 373→    // Dramatic pause scales with depth
 374→    const pauseDuration = 200 + question.depth * 100;
 375→    setTimeout(() => {
 376→      this.showQuestion(game, this.currentQuestionIndex);
 377→    }, pauseDuration);
 378→  }
 379→
 380→  /**
 381→   * CORE EVOLUTION FUNCTION
 382→   * Called after each answer — makes the garden grow
 383→   *
 384→   * MAC-CENTRIC GROWTH: Plants spawn in rings that converge toward the Mac.
 385→   * Earlier questions = plants at edges of screen (large radius)
 386→   * Later questions = plants close to the Mac (small radius)
 387→   *
 388→   * This creates the effect of the garden "enveloping" the computer.
 389→   */
 390→  evolve(game, depth, traitValue, questionId) {
 391→    // Base evolution progress (0 to 1 over all questions)
 392→    this.targetEvolution = (this.currentQuestionIndex + 1) / QUESTIONS.length;
 393→
 394→    // Stage-specific evolution (2 questions per stage)
 395→    const newStage = Math.ceil((this.currentQuestionIndex + 1) / 2);
 396→    this.stage = newStage;
 397→
 398→    // Brightness increases with evolution
 399→    this.brightness = 0.1 + this.targetEvolution * 0.4;
 400→
 401→    // === MAC-CENTRIC PLANT SPAWNING ===
 402→    // Plants grow FROM edges TOWARD the Mac
 403→    // Earlier questions = far from Mac, later questions = close to Mac
 404→    const plantCount = 3 + Math.floor(Math.random() * 2);
 405→
 406→    // Mac center (where plants converge)
 407→    const macCenterX = this.macBounds.x + this.macBounds.width / 2;
 408→    const macCenterY = this.macBounds.y + this.macBounds.height;
 409→
 410→    // Radius decreases as questions progress (converging on Mac)
 411→    // Q1-2: plants at screen edges (radius ~350-400)
 412→    // Q7-8: plants hugging the Mac (radius ~80-120)
 413→    const progress = this.currentQuestionIndex / (QUESTIONS.length - 1); // 0 to 1
 414→    const maxRadius = Math.min(game.width, game.height) * 0.45;
 415→    const minRadius = this.macBounds.width * 0.6;
 416→    const radius = maxRadius - progress * (maxRadius - minRadius);
 417→
 418→    this.garden.addPlantsAroundCenter(questionId, traitValue, macCenterX, macCenterY, radius, plantCount);
 419→
 420→    // Stage-specific effects
 421→    switch (newStage) {
 422→      case 1: // SEEDS — First stirrings of life
 423→        // Subtle, just the first plants
 424→        break;
 425→
 426→      case 2: // SPROUTS — More growth, some fireflies appear
 427→        if (Math.random() < 0.4) {
 428→          const fx = game.width * 0.2 + Math.random() * game.width * 0.6;
 429→          const fy = this.groundY - 80 - Math.random() * 100;
 430→          this.garden.addFirefly(fx, fy);
 431→        }
 432→        break;
 433→
 434→      case 3: // BLOOM — Garden flourishes, more fireflies
 435→        for (let i = 0; i < 2; i++) {
 436→          if (Math.random() < 0.5) {
 437→            const fx = game.width * 0.1 + Math.random() * game.width * 0.8;
 438→            const fy = this.groundY - 60 - Math.random() * 120;
 439→            this.garden.addFirefly(fx, fy);
 440→          }
 441→        }
 442→        this.ambientGlow = 0.1 + traitValue * 0.1;
 443→        break;
 444→
 445→      case 4: // GLOW — Full bioluminescence
 446→        this.ambientGlow = 0.3 + traitValue * 0.2;
 447→        // Extra fireflies for the finale
 448→        for (let i = 0; i < 3; i++) {
 449→          const fx = game.width * 0.1 + Math.random() * game.width * 0.8;
 450→          const fy = this.groundY - 50 - Math.random() * 150;
 451→          this.garden.addFirefly(fx, fy);
 452→        }
 453→        break;
 454→    }
 455→  }
