 521→  finishCalibration(game) {
 522→    // === DETERMINISTIC PROFILE (Legacy) ===
 523→    // Use DeterministicProfileEngine for invariant trait computation
 524→    // Same answers → Same profile. Always.
 525→    const profile = DeterministicProfileEngine.buildProfile(this.answers);
 526→
 527→    // Add confidence based on answer completeness
 528→    profile.confidence = DeterministicProfileEngine.computeConfidence(this.answers);
 529→
 530→    // === COGNITIVE PROFILE ===
 531→    // End the cognitive session and save to storage
 532→    if (this.cognitiveManager) {
 533→      const cognitiveProfile = this.cognitiveManager.endSession();
 534→      this.cognitiveManager.saveToStorage();
 535→
 536→      // Attach cognitive profile to main profile
 537→      profile.cognitive = cognitiveProfile;
 538→      profile.cognitiveInsights = this.cognitiveManager.scoringEngine
 539→        ? this.cognitiveManager.scoringEngine.analyzeEmergentPatterns(cognitiveProfile)
 540→        : [];
 541→    }
 542→
 543→    // === AESTHETIC SIGNATURE ===
 544→    // Visual signature is for display only — NOT used in AI behavior
 545→    // Garden metrics are random, so we only capture color state
 546→    profile.visualSignature = {
 547→      hue: this.colorHue,
 548→      saturation: this.colorSaturation,
 549→      brightness: this.brightness,
 550→      stage: this.stage,
 551→      // Note: Garden counts removed from profile — they're non-deterministic
 552→      // The garden is aesthetic pleasure, the profile is behavioral truth
 553→    };
 554→
 555→    game.calibrationProfile = profile;
 556→    game.changeState('profile');
 557→  }
 558→
 559→  // === UPDATE ===
 560→
 561→  update(game, dt) {
 562→    this.time += dt;
 563→
 564→    // Smooth evolution interpolation
 565→    this.evolution += (this.targetEvolution - this.evolution) * dt * 2;
 566→
 567→    // Wind animation
 568→    this.windPhase += dt * 0.8;
 569→
 570→    // Update stars
 571→    this.updateStars(dt);
 572→
 573→    // Update pixel garden with cursor position for presence response
 574→    if (this.garden) {
 575→      this.garden.setCursor(this.cursorX, this.cursorY);
 576→      this.garden.update(dt, this.time);
 577→    }
 578→  }
 579→
 580→  // ZEN: Track cursor for presence response
 581→  onPointerMove(game, x, y) {
 582→    this.cursorX = x;
 583→    this.cursorY = y;
 584→  }
 585→
 586→  updateStars(dt) {
 587→    // Stars twinkle and fade in with evolution
 588→    this.stars.forEach(star => {
 589→      star.twinklePhase += star.twinkleSpeed * dt;
 590→    });
 591→  }
 592→
 593→  // === RENDER ===
 594→
 595→  render(game, ctx) {
 596→    // === BACKGROUND ===
 597→    // Deep void black with subtle green tint
 598→    ctx.fillStyle = PALETTE.void;
 599→    ctx.fillRect(0, 0, game.width, game.height);
 600→
 601→    // Stars (fade in with evolution)
 602→    this.renderStars(ctx, game);
 603→
 604→    // Subtle glow from garden center (grows with evolution)
 605→    if (this.evolution > 0.2) {
 606→      const gradient = ctx.createRadialGradient(
 607→        game.width / 2, this.groundY, 0,
 608→        game.width / 2, this.groundY, game.height * 0.6
 609→      );
 610→      const glowAlpha = 0.05 + this.evolution * 0.1 + this.ambientGlow * 0.15;
 611→      gradient.addColorStop(0, `rgba(90, 186, 90, ${glowAlpha})`);
 612→      gradient.addColorStop(1, 'transparent');
 613→      ctx.fillStyle = gradient;
 614→      ctx.fillRect(0, 0, game.width, game.height);
 615→    }
 616→
 617→    // === GROUND ===
 618→    this.renderGround(ctx, game);
 619→
 620→    // === PIXEL GARDEN ===
 621→    // Initialize renderer if needed
 622→    if (this.garden && !this.garden.renderer) {
 623→      this.garden.setRenderer(ctx, 3); // 3px pixel size
 624→    }
 625→    if (this.garden) {
 626→      this.garden.render(this.time);
 627→    }
 628→
 629→    // === AMBIENT GLOW (stage 4) ===
 630→    if (this.ambientGlow > 0) {
 631→      this.renderBioluminescence(ctx, game);
 632→    }
 633→
 634→    // === MAC ===
 635→    this.renderMac(ctx, game);
 636→
 637→    // === POST-PROCESSING: VIGNETTE ===
 638→    // Darkens edges to focus attention on center
 639→    this.renderVignette(ctx, game);
 640→  }
 641→
 642→  // IMPACT: Post-processing vignette effect
 643→  renderVignette(ctx, game) {
 644→    const gradient = ctx.createRadialGradient(
 645→      game.width / 2, game.height / 2, game.height * 0.25,
 646→      game.width / 2, game.height / 2, game.height * 0.9
 647→    );
 648→    gradient.addColorStop(0, 'rgba(0,0,0,0)');
 649→    gradient.addColorStop(0.5, 'rgba(0,0,0,0.1)');
 650→    gradient.addColorStop(1, 'rgba(0,0,0,0.5)');
 651→    ctx.fillStyle = gradient;
 652→    ctx.fillRect(0, 0, game.width, game.height);
 653→  }
 654→
 655→  renderGround(ctx, game) {
 656→    // Ground gradient - dark soil fading to black
 657→    const groundGradient = ctx.createLinearGradient(0, this.groundY - 20, 0, game.height);
 658→    groundGradient.addColorStop(0, 'transparent');
 659→    groundGradient.addColorStop(0.1, PALETTE.darkest);
 660→    groundGradient.addColorStop(1, PALETTE.void);
 661→
 662→    ctx.fillStyle = groundGradient;
 663→    ctx.fillRect(0, this.groundY - 20, game.width, game.height - this.groundY + 20);
 664→
 665→    // Ground line (subtle)
 666→    ctx.fillStyle = PALETTE.darker;
 667→    ctx.fillRect(0, this.groundY, game.width, 3);
 668→  }
 669→
 670→  renderBioluminescence(ctx, game) {
 671→    // Overall ambient glow that pulses
 672→    const pulse = 0.7 + Math.sin(this.time * 0.5) * 0.3;
 673→
 674→    const gradient = ctx.createRadialGradient(
 675→      game.width / 2, this.groundY - 50, 0,
 676→      game.width / 2, this.groundY - 50, game.width * 0.5
 677→    );
 678→    gradient.addColorStop(0, `rgba(90, 186, 90, ${this.ambientGlow * 0.1 * pulse})`);
 679→    gradient.addColorStop(1, 'transparent');
 680→
 681→    ctx.fillStyle = gradient;
 682→    ctx.fillRect(0, 0, game.width, game.height);
 683→  }
 684→
 685→  renderStars(ctx, game) {
 686→    // Stars fade in with evolution — the sky awakens
 687→    const starAlpha = Math.max(0, (this.evolution - 0.1) * 1.2);
 688→    if (starAlpha <= 0) return;
 689→
 690→    this.stars.forEach(star => {
 691→      const twinkle = 0.5 + Math.sin(star.twinklePhase) * 0.5;
 692→      const alpha = starAlpha * star.brightness * twinkle;
 693→
 694→      // Star glow (stage 3+)
 695→      if (this.stage >= 3) {
 696→        ctx.fillStyle = `rgba(170, 255, 170, ${alpha * 0.2})`;
 697→        ctx.beginPath();
 698→        ctx.arc(star.x, star.y, star.size * 3, 0, Math.PI * 2);
 699→        ctx.fill();
 700→      }
 701→
 702→      // Star core
 703→      ctx.fillStyle = `rgba(170, 255, 170, ${alpha})`;
 704→      ctx.beginPath();
 705→      ctx.arc(star.x, star.y, star.size, 0, Math.PI * 2);
 706→      ctx.fill();
 707→    });
 708→  }
 709→
 710→  renderMac(ctx, game) {
 711→    const m = this.macBounds;
 712→    const s = this.screenBounds;
 713→
 714→    // === 3D CABINET PROJECTION ===
 715→    // Depth recedes at 30 degrees up-right (consistent vanishing direction)
 716→    const depth = m.height * 0.12;
 717→    const depthX = depth * 0.866; // cos(30°)
 718→    const depthY = depth * 0.5;   // sin(30°)
 719→
 720→    // === 1. GROUND SHADOW ===
 721→    ctx.save();
 722→    const shadowGrad = ctx.createRadialGradient(
 723→      m.x + m.width / 2, m.y + m.height + 8,
 724→      m.width * 0.1,
 725→      m.x + m.width / 2, m.y + m.height + 8,
 726→      m.width * 0.6
 727→    );
 728→    shadowGrad.addColorStop(0, 'rgba(0, 0, 0, 0.5)');
 729→    shadowGrad.addColorStop(0.5, 'rgba(0, 0, 0, 0.2)');
 730→    shadowGrad.addColorStop(1, 'rgba(0, 0, 0, 0)');
 731→    ctx.fillStyle = shadowGrad;
 732→    ctx.beginPath();
 733→    ctx.ellipse(m.x + m.width / 2, m.y + m.height + 8, m.width * 0.55, 12, 0, 0, Math.PI * 2);
 734→    ctx.fill();
 735→    ctx.restore();
 736→
 737→    // === 2. BACK EDGES (draw first, behind everything) ===
 738→    // These create the illusion of depth by showing where the back of the box would be
 739→
 740→    // === 3. RIGHT SIDE PANEL (visible depth - shadow side) ===
 741→    ctx.beginPath();
 742→    ctx.moveTo(m.x + m.width, m.y + 8);                           // Front top-right
 743→    ctx.lineTo(m.x + m.width + depthX, m.y + 8 - depthY);         // Back top-right
 744→    ctx.lineTo(m.x + m.width + depthX, m.y + m.height - 8 - depthY); // Back bottom-right
 745→    ctx.lineTo(m.x + m.width, m.y + m.height - 8);                // Front bottom-right
 746→    ctx.closePath();
 747→
 748→    // Gradient from front (lighter) to back (darker)
 749→    const sideGrad = ctx.createLinearGradient(
 750→      m.x + m.width, m.y,
 751→      m.x + m.width + depthX, m.y - depthY
 752→    );
 753→    sideGrad.addColorStop(0, '#c8c0b0');
 754→    sideGrad.addColorStop(1, '#a8a090');
 755→    ctx.fillStyle = sideGrad;
 756→    ctx.fill();
 757→    ctx.strokeStyle = '#706860';
 758→    ctx.lineWidth = 1;
 759→    ctx.stroke();
 760→
 761→    // === 4. TOP PANEL (visible depth - lit side) ===
 762→    ctx.beginPath();
 763→    ctx.moveTo(m.x + 8, m.y);                                     // Front top-left
 764→    ctx.lineTo(m.x + 8 + depthX, m.y - depthY);                   // Back top-left
 765→    ctx.lineTo(m.x + m.width - 8 + depthX, m.y - depthY);         // Back top-right
 766→    ctx.lineTo(m.x + m.width + depthX, m.y + 8 - depthY);         // Connect to side
 767→    ctx.lineTo(m.x + m.width, m.y + 8);                           // Front top-right corner
 768→    ctx.lineTo(m.x + m.width - 8, m.y);                           // Front top-right
 769→    ctx.closePath();
 770→
 771→    // Top catches light
 772→    const topGrad = ctx.createLinearGradient(
 773→      m.x, m.y,
 774→      m.x + depthX, m.y - depthY
 775→    );
 776→    topGrad.addColorStop(0, '#f0e8d8');
 777→    topGrad.addColorStop(1, '#e0d8c8');
 778→    ctx.fillStyle = topGrad;
 779→    ctx.fill();
 780→    ctx.strokeStyle = '#b0a898';
 781→    ctx.lineWidth = 1;
 782→    ctx.stroke();
 783→
 784→    // === 5. FRONT FACE (main body) ===
 785→    const bodyGrad = ctx.createLinearGradient(m.x, m.y, m.x, m.y + m.height);
 786→    bodyGrad.addColorStop(0, '#f5ede0');
 787→    bodyGrad.addColorStop(0.4, '#e8e0d0');
 788→    bodyGrad.addColorStop(1, '#d8d0c0');
 789→    ctx.fillStyle = bodyGrad;
 790→    ctx.strokeStyle = '#504840';
 791→    ctx.lineWidth = 2;
 792→    this.roundRect(ctx, m.x, m.y, m.width, m.height, 8);
 793→    ctx.fill();
 794→    ctx.stroke();
 795→
 796→    // Front face bevel highlights
 797→    ctx.strokeStyle = 'rgba(255,255,255,0.4)';
 798→    ctx.lineWidth = 2;
 799→    ctx.beginPath();
 800→    ctx.moveTo(m.x + 8, m.y + 2);
 801→    ctx.lineTo(m.x + m.width - 8, m.y + 2);
 802→    ctx.stroke();
 803→    ctx.beginPath();
 804→    ctx.moveTo(m.x + 2, m.y + 8);
 805→    ctx.lineTo(m.x + 2, m.y + m.height - 8);
 806→    ctx.stroke();
 807→
 808→    // Front face shadow edges
 809→    ctx.strokeStyle = 'rgba(0,0,0,0.15)';
 810→    ctx.lineWidth = 2;
 811→    ctx.beginPath();
 812→    ctx.moveTo(m.x + 8, m.y + m.height - 2);
 813→    ctx.lineTo(m.x + m.width - 8, m.y + m.height - 2);
 814→    ctx.stroke();
 815→    ctx.beginPath();
 816→    ctx.moveTo(m.x + m.width - 2, m.y + 8);
 817→    ctx.lineTo(m.x + m.width - 2, m.y + m.height - 8);
 818→    ctx.stroke();
 819→
 820→    // === 6. SCREEN BEZEL (recessed) ===
 821→    // Outer bezel (dark recess)
 822→    ctx.fillStyle = '#0a0a0a';
 823→    this.roundRect(ctx, s.x - 6, s.y - 6, s.width + 12, s.height + 12, 4);
 824→    ctx.fill();
 825→
 826→    // Bezel rim with 3D inset effect
 827→    ctx.strokeStyle = '#404040';
 828→    ctx.lineWidth = 1;
 829→    ctx.beginPath();
 830→    ctx.moveTo(s.x - 5, s.y + s.height + 5);
 831→    ctx.lineTo(s.x - 5, s.y - 5);
 832→    ctx.lineTo(s.x + s.width + 5, s.y - 5);
 833→    ctx.stroke();
 834→    ctx.strokeStyle = '#1a1a1a';
 835→    ctx.beginPath();
 836→    ctx.moveTo(s.x + s.width + 5, s.y - 5);
 837→    ctx.lineTo(s.x + s.width + 5, s.y + s.height + 5);
 838→    ctx.lineTo(s.x - 5, s.y + s.height + 5);
 839→    ctx.stroke();
 840→
 841→    // === 7. CRT SCREEN ===
 842→    ctx.fillStyle = '#0a150a';
 843→    ctx.fillRect(s.x, s.y, s.width, s.height);
 844→
 845→    // CRT glass curvature (darker at edges)
 846→    const crtCurve = ctx.createRadialGradient(
 847→      s.x + s.width / 2, s.y + s.height / 2, 0,
 848→      s.x + s.width / 2, s.y + s.height / 2, s.width * 0.7
 849→    );
 850→    crtCurve.addColorStop(0, 'rgba(0,0,0,0)');
 851→    crtCurve.addColorStop(0.6, 'rgba(0,0,0,0.05)');
 852→    crtCurve.addColorStop(1, 'rgba(0,0,0,0.3)');
 853→    ctx.fillStyle = crtCurve;
 854→    ctx.fillRect(s.x, s.y, s.width, s.height);
 855→
 856→    // Glass reflection
 857→    ctx.fillStyle = 'rgba(120, 180, 120, 0.04)';
 858→    ctx.beginPath();
 859→    ctx.ellipse(s.x + s.width * 0.3, s.y + s.height * 0.25, s.width * 0.4, s.height * 0.2, -0.3, 0, Math.PI * 2);
 860→    ctx.fill();
 861→
 862→    // === 8. PHOSPHOR GLOW ===
 863→    const plantCount = this.garden ? this.garden.getMaturePlantCount() : 0;
 864→    const gardenHealth = Math.min(1, plantCount / 6);
 865→    const breath = Math.sin(this.time * 0.17) * 0.5 + 0.5;
 866→    const glowIntensity = 0.03 + gardenHealth * 0.12 + (gardenHealth > 0.3 ? breath * 0.05 : 0);
 867→
 868→    const glow = ctx.createRadialGradient(
 869→      s.x + s.width / 2, s.y + s.height / 2, 0,
 870→      s.x + s.width / 2, s.y + s.height / 2, s.width * 0.7
 871→    );
 872→    const warmth = 80 + gardenHealth * 40;
 873→    glow.addColorStop(0, `rgba(${warmth}, ${150 + gardenHealth * 50}, ${warmth}, ${glowIntensity})`);
 874→    glow.addColorStop(1, 'transparent');
 875→    ctx.fillStyle = glow;
 876→    ctx.fillRect(s.x, s.y, s.width, s.height);
 877→
 878→    // Scanlines
 879→    ctx.fillStyle = 'rgba(0, 0, 0, 0.05)';
 880→    for (let y = s.y; y < s.y + s.height; y += 3) {
 881→      ctx.fillRect(s.x, y, s.width, 1);
 882→    }
 883→
 884→    // === 9. CHIN AREA ===
 885→    const chinY = s.y + s.height + 10;
 886→
 887→    // Disk slot (3D inset)
 888→    const slotWidth = m.width * 0.20;
 889→    const slotX = m.x + m.width / 2 - slotWidth / 2;
 890→    ctx.fillStyle = '#1a1a1a';
 891→    this.roundRect(ctx, slotX, chinY + 12, slotWidth, 6, 2);
 892→    ctx.fill();
 893→    // Slot top edge shadow
 894→    ctx.strokeStyle = '#303030';
 895→    ctx.lineWidth = 1;
 896→    ctx.beginPath();
 897→    ctx.moveTo(slotX + 2, chinY + 12);
 898→    ctx.lineTo(slotX + slotWidth - 2, chinY + 12);
 899→    ctx.stroke();
 900→    // Slot bottom edge highlight
 901→    ctx.strokeStyle = '#0a0a0a';
 902→    ctx.beginPath();
 903→    ctx.moveTo(slotX + 2, chinY + 17);
 904→    ctx.lineTo(slotX + slotWidth - 2, chinY + 17);
 905→    ctx.stroke();
 906→
 907→    // === 10. VENTS (3D grooves) ===
 908→    const ventCount = 6;
 909→    const ventSpacing = m.height * 0.015;
 910→    const ventStartY = m.y + m.height * 0.05;
 911→
 912→    for (let i = 0; i < ventCount; i++) {
 913→      const vy = ventStartY + i * ventSpacing;
 914→
 915→      // Left vents - shadow then highlight for groove effect
 916→      ctx.strokeStyle = '#a09888';
 917→      ctx.lineWidth = 2;
 918→      ctx.beginPath();
 919→      ctx.moveTo(m.x + 6, vy);
 920→      ctx.lineTo(m.x + 16, vy);
 921→      ctx.stroke();
 922→      ctx.strokeStyle = '#e8e0d0';
 923→      ctx.lineWidth = 1;
 924→      ctx.beginPath();
 925→      ctx.moveTo(m.x + 6, vy + 2);
 926→      ctx.lineTo(m.x + 16, vy + 2);
 927→      ctx.stroke();
 928→
 929→      // Right vents
 930→      ctx.strokeStyle = '#a09888';
 931→      ctx.lineWidth = 2;
 932→      ctx.beginPath();
 933→      ctx.moveTo(m.x + m.width - 16, vy);
 934→      ctx.lineTo(m.x + m.width - 6, vy);
 935→      ctx.stroke();
 936→      ctx.strokeStyle = '#e8e0d0';
 937→      ctx.lineWidth = 1;
 938→      ctx.beginPath();
 939→      ctx.moveTo(m.x + m.width - 16, vy + 2);
 940→      ctx.lineTo(m.x + m.width - 6, vy + 2);
 941→      ctx.stroke();
 942→    }
 943→
 944→    // === 11. SCREEN LIGHT SPILL onto body ===
 945→    if (gardenHealth > 0.2) {
 946→      const spillGrad = ctx.createRadialGradient(
 947→        s.x + s.width / 2, s.y + s.height, 0,
 948→        s.x + s.width / 2, chinY + 40, s.width * 0.4
 949→      );
 950→      spillGrad.addColorStop(0, `rgba(100, 180, 100, ${0.08 * gardenHealth})`);
 951→      spillGrad.addColorStop(1, 'transparent');
 952→      ctx.fillStyle = spillGrad;
 953→      ctx.fillRect(m.x, s.y + s.height, m.width, m.height - (s.y + s.height - m.y));
 954→    }
 955→  }
