 957→  roundRect(ctx, x, y, w, h, r) {
 958→    ctx.beginPath();
 959→    ctx.moveTo(x + r, y);
 960→    ctx.lineTo(x + w - r, y);
 961→    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
 962→    ctx.lineTo(x + w, y + h - r);
 963→    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
 964→    ctx.lineTo(x + r, y + h);
 965→    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
 966→    ctx.lineTo(x, y + r);
 967→    ctx.quadraticCurveTo(x, y, x + r, y);
 968→    ctx.closePath();
 969→  }
