 92→      <div class="export-options" style="margin-top: 16px; display: flex; gap: 8px; justify-content: center; flex-wrap: wrap;">
 93→        <button class="btn small accent" id="copyAnchorBtn" title="Copy anchor for AI recognition">Copy Anchor</button>
 94→        <button class="btn small" id="downloadMdBtn" title="Download Markdown with anchor">Markdown</button>
 95→        <button class="btn small" id="downloadUsdaBtn" title="Download as USD (Universal Scene Description)">USDA</button>
 96→        <button class="btn small" id="downloadJsonBtn" title="Download as JSON">JSON</button>
 97→      </div>
 98→
 99→      <button class="btn secondary" id="restartBtn" style="margin-top: 16px;">${DIALOGUE.ui.restartButton}</button>
100→    `;
101→
102→    game.ui.appendChild(this.overlay);
103→
104→    // Trigger reflow then add visible class
105→    this.overlay.offsetHeight;
106→    this.overlay.classList.add('visible');
107→
108→    // Bind buttons
109→    this.overlay.querySelector('#copyBtn').onclick = () => this.copyProfile(game);
110→    this.overlay.querySelector('#copyAnchorBtn').onclick = () => this.copyAnchor();
111→    this.overlay.querySelector('#downloadMdBtn').onclick = () => this.downloadMarkdown();
112→    this.overlay.querySelector('#downloadUsdaBtn').onclick = () => this.downloadUSDA();
113→    this.overlay.querySelector('#downloadJsonBtn').onclick = () => this.downloadJSON();
114→    this.overlay.querySelector('#restartBtn').onclick = () => game.restart();
115→  }
