117→  buildTraitsHTML() {
118→    const { traits } = this.profile;
119→
120→    // Dynamic trait order based on what dimensions were measured
121→    const allDimensions = [
122→      { key: 'pace', name: 'Pace' },
123→      { key: 'thoroughness', name: 'Detail Preference' },
124→      { key: 'organization', name: 'Structure' },
125→      { key: 'exploration', name: 'Problem Solving' },
126→      { key: 'communication', name: 'Feedback Style' },
127→      { key: 'ambiguity', name: 'Uncertainty' },
128→      { key: 'rhythm', name: 'Conversation Rhythm' },
129→      { key: 'tangents', name: 'Tangents' }
130→    ];
131→
132→    return allDimensions.map(t => {
133→      const trait = traits[t.key];
134→      if (!trait) return '';
135→      return `
136→        <div class="trait">
137→          <span class="trait-name">${t.name}</span>
138→          <span class="trait-value">${trait.label || 'Balanced'}</span>
