189→  /**
190→   * Build cognitive profile insights display
191→   * Shows empowering insights from deep cognitive profiling
192→   */
193→  buildCognitiveHTML() {
194→    if (!this.renderedCognitive || !this.renderedCognitive.sections.length) {
195→      return '';
196→    }
197→
198→    const { sections, emergentInsights, completeness } = this.renderedCognitive;
199→
200→    let html = `
